#[derive(Clone, Debug)]
pub struct OpsStateClient {
    read: NativeRequestHandle<OpsStateRead>,
    receipt: NativeRequestHandle<OpsStateReceipt>,
    update: NativeRequestHandle<OpsStateUpdate>,
}
impl OpsStateClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn read(&self, request: ReadRequest) -> Result<ReadResponse, OpsStateReadInvocationError> {
        self.read.invoke(READ_OPERATION, request).await
            .map_err(OpsStateReadInvocationError::Runtime)?
            .map_err(OpsStateReadInvocationError::Domain)
    }

    pub async fn read_with_context(&self, context: InvocationContext, request: ReadRequest) -> Result<ReadResponse, OpsStateReadInvocationError> {
        self.read.invoke_with_context(READ_OPERATION, context, request).await
            .map_err(OpsStateReadInvocationError::Runtime)?
            .map_err(OpsStateReadInvocationError::Domain)
    }

    pub async fn receipt(&self, request: ReceiptRequest) -> Result<ReceiptResponse, OpsStateReceiptInvocationError> {
        self.receipt.invoke(RECEIPT_OPERATION, request).await
            .map_err(OpsStateReceiptInvocationError::Runtime)?
            .map_err(OpsStateReceiptInvocationError::Domain)
    }

    pub async fn receipt_with_context(&self, context: InvocationContext, request: ReceiptRequest) -> Result<ReceiptResponse, OpsStateReceiptInvocationError> {
        self.receipt.invoke_with_context(RECEIPT_OPERATION, context, request).await
            .map_err(OpsStateReceiptInvocationError::Runtime)?
            .map_err(OpsStateReceiptInvocationError::Domain)
    }

    pub async fn update(&self, request: UpdateRequest) -> Result<UpdateResponse, OpsStateUpdateInvocationError> {
        self.update.invoke(UPDATE_OPERATION, request).await
            .map_err(OpsStateUpdateInvocationError::Runtime)?
            .map_err(OpsStateUpdateInvocationError::Domain)
    }

    pub async fn update_with_context(&self, context: InvocationContext, request: UpdateRequest) -> Result<UpdateResponse, OpsStateUpdateInvocationError> {
        self.update.invoke_with_context(UPDATE_OPERATION, context, request).await
            .map_err(OpsStateUpdateInvocationError::Runtime)?
            .map_err(OpsStateUpdateInvocationError::Domain)
    }
}

impl CapabilityClient for OpsStateClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            read: dependencies.one::<OpsStateRead>()?,
            receipt: dependencies.one::<OpsStateReceipt>()?,
            update: dependencies.one::<OpsStateUpdate>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for OpsStateClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    read: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OpsStateRead>()?,
                    receipt: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OpsStateReceipt>()?,
                    update: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<OpsStateUpdate>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

